        "sampleValue": "已完成"
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "跳转到音乐或听书应用的短按钮文案",
        "sampleValue": "听书"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/music_fill.svg",
      "description": "音乐音符实心图标，适合表达听书、音频内容或音乐应用入口。"
    }
  ]
}

